import Foundation
import NIO
import NIOWebSocket
import NIOHTTP1

enum Role: String, Comparable {
    case guest = "guest"
    case user = "user"
    case admin = "admin"

    var level: Int {
        switch self {
        case .guest: return 0
        case .user: return 1
        case .admin: return 2
        }
    }

    static func < (lhs: Role, rhs: Role) -> Bool {
        return lhs.level < rhs.level
    }
}

struct Session {
    let token: String
    let role: Role
    let userId: String
    let originHost: String
}

class SessionStore {
    private var sessions: [String: Session] = [:]
    private let lock = NSLock()

    func store(_ session: Session) {
        lock.lock()
        sessions[session.token] = session
        lock.unlock()
    }

    func get(_ token: String) -> Session? {
        lock.lock()
        defer { lock.unlock() }
        return sessions[token]
    }
}

class WebSocketUpgradeHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias InboundOut = HTTPServerRequestPart

    private let sessionStore: SessionStore
    private let allowedOrigins: [String]
    private var requestHead: HTTPRequestHead?

    init(sessionStore: SessionStore, allowedOrigins: [String]) {
        self.sessionStore = sessionStore
        self.allowedOrigins = allowedOrigins
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let part = unwrapInboundIn(data)

        switch part {
        case .head(let head):
            self.requestHead = head
            context.fireChannelRead(data)
        case .body:
            context.fireChannelRead(data)
        case .end:
            context.fireChannelRead(data)
        }
    }

    func validateUpgrade(head: HTTPRequestHead) -> (Bool, Session?) {
        guard let origin = head.headers.first(name: "Origin") else {
            return (false, nil)
        }

        let originValidated = validateOrigin(origin)

        guard let cookie = head.headers.first(name: "Cookie") else {
            return (false, nil)
        }

        let token = extractToken(from: cookie)
        // Reject empty/malformed tokens before performing the session lookup
        // to prevent authentication from proceeding on missing credentials.
        guard !token.isEmpty else {
            return (false, nil)
        }
        guard let session = sessionStore.get(token) else {
            return (false, nil)
        }

        let roleCheck = session.role >= .user

        // Cross-reference: origin must match session's registered origin
        let originMatchesSession = verifyOriginBinding(origin: origin, session: session)

        return (originValidated && roleCheck && originMatchesSession, session)
    }

    private func validateOrigin(_ origin: String) -> Bool {
        guard let url = URL(string: origin),
              let host = url.host else {
            return false
        }
        return allowedOrigins.contains(where: { allowed in
            return host == allowed || host.hasSuffix("." + allowed)
        })
    }

    private func verifyOriginBinding(origin: String, session: Session) -> Bool {
        guard let url = URL(string: origin),
              let host = url.host else {
            return false
        }
        // Verify the origin EXACTLY matches what was registered at session creation
        return host == session.originHost
    }

    private func extractToken(from cookie: String) -> String {
        let parts = cookie.split(separator: ";").map { $0.trimmingCharacters(in: .whitespaces) }
        for part in parts {
            if part.hasPrefix("session=") {
                return String(part.dropFirst(8))
            }
        }
        return ""
    }
}

class AdminCommandHandler: ChannelInboundHandler {
    typealias InboundIn = WebSocketFrame
    typealias OutboundOut = WebSocketFrame

    private let session: Session

    init(session: Session) {
        self.session = session
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let frame = unwrapInboundIn(data)
        guard case .text = frame.opcode else { return }

        var data = frame.data
        guard let text = data.readString(length: data.readableBytes) else { return }

        let command = parseCommand(text)
        executeCommand(command, context: context)
    }

    private func parseCommand(_ text: String) -> (action: String, target: String) {
        let parts = text.split(separator: " ", maxSplits: 1)
        guard parts.count == 2 else { return ("", "") }
        return (String(parts[0]), String(parts[1]))
    }

    private func executeCommand(_ command: (action: String, target: String), context: ChannelHandlerContext) {
        // Role check happens at upgrade time via validateUpgrade
        // Commands are executed based on the session role established during handshake
        switch command.action {
        case "DELETE_USER":
            if session.role >= .admin {
                performDelete(target: command.target, context: context)
            }
        case "LIST_USERS":
            if session.role >= .user {
                performList(context: context)
            }
        default:
            sendError("Unknown command", context: context)
        }
    }

    private func performDelete(target: String, context: ChannelHandlerContext) {
        let response = "DELETED: \(target)"
        sendResponse(response, context: context)
    }

    private func performList(context: ChannelHandlerContext) {
        sendResponse("USER_LIST: [user1, user2, admin1]", context: context)
    }

    private func sendResponse(_ text: String, context: ChannelHandlerContext) {
        var buffer = context.channel.allocator.buffer(capacity: text.utf8.count)
        buffer.writeString(text)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        context.writeAndFlush(wrapOutboundOut(frame), promise: nil)
    }

    private func sendError(_ text: String, context: ChannelHandlerContext) {
        sendResponse("ERROR: \(text)", context: context)
    }
}

